    // Practice Questions
    async getQuestions(f) {
      let qs = DATA.questions || [];
      if (f && f.course) qs = qs.filter(function(q) { return q.course_id === f.course; });
      if (f && f.difficulty) qs = qs.filter(function(q) { return (q.difficulty || '').toLowerCase() === f.difficulty.toLowerCase(); });
      return { success: true, questions: qs };
    },
    async getQuestion(id) {
      const q = (DATA.questions || []).find(function(item) { return item.id === id; }) || DATA.questions[0];
      return { question: q, correct: true, score: 100, explanation: q.explanation };
    },
    async attemptQuestion(id, r) {
      const user = getActiveUser();
      if (user) {
        const prog = getUserProgress(user.id);
        if (!prog.question_attempts) prog.question_attempts = {};
        prog.question_attempts[id] = true;
        saveUserProgress(user.id, prog);
        user.xp = (user.xp || 50) + 10;
        localStorage.setItem('ap_user', JSON.stringify(user));
        if (window.State) window.State.setUser(user);
      }
      return { correct: true, score: 100, explanation: 'Verified answer.' };
    },
    async submitQuestionAttempt(id, r) { return this.attemptQuestion(id, r); },
    async getWeakQuestions() { return { questions: (DATA.questions || []).slice(0, 3) }; },

    // Schedule
    async getSchedule() {
      const user = getActiveUser();
      return { schedule: getUserSchedule(user ? user.id : null) };
    },
    async rescheduleMissed() {
      const user = getActiveUser();
      const sched = getUserSchedule(user ? user.id : null);
      sched.forEach(function(t) { t.is_completed = false; });
      saveUserSchedule(user ? user.id : null, sched);
      return { success: true, message: 'All overdue study sessions successfully pushed into upcoming open days!' };
    },
    async toggleTask(id) {
      const user = getActiveUser();
      const sched = getUserSchedule(user ? user.id : null);
      const task = sched.find(function(t) { return t.id === id; });
      if (task) {
        task.is_completed = !task.is_completed;
        saveUserSchedule(user ? user.id : null, sched);
      }
      return { success: true, message: 'Task status updated!' };
    },
    async deleteScheduleTask(id) {
      const user = getActiveUser();
      let sched = getUserSchedule(user ? user.id : null);
      sched = sched.filter(function(t) { return t.id !== id; });
      saveUserSchedule(user ? user.id : null, sched);
      return { success: true, message: 'Task deleted' };
    },
    async bulkMoveSchedule(d) { return { success: true, message: 'Schedule successfully shifted!' }; },
    async rebalanceSchedule() { return { success: true, message: 'Study plan rebalanced evenly across the week!' }; },
    async addScheduleTask(d) {
      const user = getActiveUser();
      const sched = getUserSchedule(user ? user.id : null);
      const newTask = {
        id: 'task_' + Date.now(),
        day_name: d.date_str ? new Date(d.date_str).toLocaleDateString('en-US', { weekday: 'long' }) : 'Flexible Day',
        date_str: d.date_str || new Date().toISOString().split('T')[0],
        duration_minutes: Number(d.duration_minutes) || 30,
        task_title: d.task_title || 'Study Session',
        task_title_hi: d.task_title || 'अध्ययन सत्र',
        task_type: d.task_type || 'custom',
        is_completed: false,
        notes: d.notes || ''
      };
      sched.push(newTask);
      saveUserSchedule(user ? user.id : null, sched);
      return { success: true, message: 'Custom study task added successfully!' };
    },

