    async addGroupGoal(groupId, text) {
      const user = getActiveUser();
      const squads = getUserSquads(user ? user.id : null);
      const squad = squads.find(function(s) { return s.id === groupId; }) || squads[0];
      if (squad) {
        if (!squad.sharedGoals) squad.sharedGoals = [];
        squad.sharedGoals.push({ id: 'g_' + Date.now(), goal_text: text, is_completed: false });
        saveUserSquads(user ? user.id : null, squads);
      }
      return { success: true };
    },

    async toggleGroupGoal(groupId, goalId) {
      const user = getActiveUser();
      const squads = getUserSquads(user ? user.id : null);
      const squad = squads.find(function(s) { return s.id === groupId; }) || squads[0];
      if (squad && squad.sharedGoals) {
        const g = squad.sharedGoals.find(function(item) { return item.id === goalId; });
        if (g) g.is_completed = !g.is_completed;
        saveUserSquads(user ? user.id : null, squads);
      }
      return { success: true };
    },

    async sendMilestoneReaction(groupId, msId, reactionType) {
      const user = getActiveUser();
      const squads = getUserSquads(user ? user.id : null);
      const squad = squads.find(function(s) { return s.id === groupId; }) || squads[0];
      if (squad && squad.milestones) {
        const ms = squad.milestones.find(function(item) { return item.id === msId; });
        if (ms) {
          if (!ms.reactions) ms.reactions = [];
          ms.reactions.push({ reaction_type: reactionType, user_name: user ? user.name : 'You' });
          saveUserSquads(user ? user.id : null, squads);
        }
      }
      return { success: true };
    },

    async getChatMessages(groupId) {
      const user = getActiveUser();
      const squads = getUserSquads(user ? user.id : null);
      const squad = squads.find(function(s) { return s.id === groupId; }) || squads[0];
      return { success: true, messages: (squad && squad.messages) || [] };
    },

    async sendChatMessage(groupId, text) {
      const user = getActiveUser() || { name: 'You', id: 'usr_me' };
      const squads = getUserSquads(user.id);
      const squad = squads.find(function(s) { return s.id === groupId; }) || squads[0];
      if (squad) {
        if (!squad.messages) squad.messages = [];
        squad.messages.push({
          sender_id: user.id,
          sender_name: user.name,
          message: text,
          created_at: new Date().toISOString()
        });
        saveUserSquads(user.id, squads);

        setTimeout(function() {
          try {
            const sqs = getUserSquads(user.id);
            const sq = sqs.find(function(s) { return s.id === groupId; }) || sqs[0];
            if (sq && sq.messages) {
              const replies = [
                'Awesome! I am working on the same analytical module right now. Let us push our streak! 🔥',
                'Great question! Did you test the SQL query with different JOIN types?',
                'Got it! Let us review the model solution and rubric together. Keep it up! 🚀'
              ];
              const rep = replies[Math.floor(Math.random() * replies.length)];
              sq.messages.push({
                sender_id: 'usr_partner',
                sender_name: 'Study Partner',
                message: rep,
                created_at: new Date().toISOString()
              });
              saveUserSquads(user.id, sqs);
            }
          } catch (e) {}
        }, 800);
      }
      return { success: true };
    },

